insert into public.templates (slug, legacy_slug, name, category, blurb, sort_order, preview_images) values
  ('birthday', 'birthday-template', 'Birthday 1', 'Birthdays', 'Turn any birthday into headline news with a fun, personalized newspaper-style template — perfect for parties, posts, or keepsakes.', 1, array['/templates/birthday/1.jpg', '/templates/birthday/2.jpg', '/templates/birthday/3.jpg', '/templates/birthday/4.jpg']::text[]),
  ('birthday-2', 'birthday-template-2', 'Birthday 2', 'Birthdays', 'A celebration of the lives we''ve lived and the moments that shaped us—every laugh, every tear, every wild detour. This is where memories rise, milestones shine, and another chapter begins with a bang.', 2, array['/templates/birthday-2/1.png', '/templates/birthday-2/2.png', '/templates/birthday-2/3.png', '/templates/birthday-2/4.png']::text[]),
  ('anniversary', 'anniversary-template', 'Anniversary', 'Anniversary', 'Celebrate love like it''s front-page news with a custom anniversary newspaper — a fun, personal way to relive the story of "us."', 3, array['/templates/anniversary/1.jpg', '/templates/anniversary/2.jpg', '/templates/anniversary/3.jpg', '/templates/anniversary/4.jpg']::text[]),
  ('retirement', 'retirement-template', 'Retirement', 'Retirements', 'Mark the end of an era with a personalized retirement newspaper — a memorable tribute to years of hard work, impact, and office legends.', 4, array['/templates/retirement/1.jpg', '/templates/retirement/2.jpg', '/templates/retirement/3.jpg']::text[]),
  ('mothers-fathers-day', 'mothers-day-template', 'Mother''s / Father''s Day', 'Mother''s & Father''s day', 'Celebrate Mom like the star she is with a custom newspaper — filled with love, laughs, and headline-worthy memories.', 5, array['/templates/mothers-fathers-day/1.jpg', '/templates/mothers-fathers-day/2.jpg', '/templates/mothers-fathers-day/3.jpg', '/templates/mothers-fathers-day/4.jpg']::text[]),
  ('summer-camp', 'summer-camp-template', 'Summer Camp', 'Summer camp souvenir', 'Capture campfire laughs and adventure-packed days with a custom summer camp newspaper — the perfect keepsake for unforgettable memories.', 6, array['/templates/summer-camp/1.jpg', '/templates/summer-camp/2.jpg', '/templates/summer-camp/3.jpg', '/templates/summer-camp/4.jpg']::text[]),
  ('menu', 'menu-template', 'Menu', 'Menu', 'Serve up your dishes in style with a custom newspaper-style menu — a unique way to add charm and character to any dining experience.', 7, array['/templates/menu/1.jpg', '/templates/menu/2.jpg', '/templates/menu/3.jpg', '/templates/menu/4.jpg']::text[]),
  ('christian-wedding', 'christan-wedding-template', 'Wedding 1', 'Wedding', 'A celebration of love, faith, and forever. This wedding brings together two souls in holy matrimony, surrounded by blessings, vows, and cherished traditions—captured in timeless memories.', 8, array['/templates/christian-wedding/1.jpg', '/templates/christian-wedding/2.jpg', '/templates/christian-wedding/3.jpg', '/templates/christian-wedding/4.jpg']::text[]),
  ('muslim-wedding', 'muslim-wedding-template', 'Wedding 2', 'Wedding', 'A heartfelt union under the light of tradition and prayer. This Nikah ceremony marks the beginning of a shared journey built on love, faith, and divine blessings—honoring sacred customs and celebrating new beginnings.', 9, array['/templates/muslim-wedding/1.jpg', '/templates/muslim-wedding/2.jpg', '/templates/muslim-wedding/3.jpg', '/templates/muslim-wedding/4.jpg']::text[]),
  ('basketball-tribute', 'basketball-tribute', 'Sports Tribute', 'Sports tribute', 'A tribute to the court kings and queens who gave it their all—every bounce, every shot, every heartbeat. This is where hustle meets passion, where teamwork makes history, and where love for the game lives on.', 10, array['/templates/basketball-tribute/1.jpg', '/templates/basketball-tribute/2.jpg', '/templates/basketball-tribute/3.jpg', '/templates/basketball-tribute/4.jpg']::text[]),
  ('events', 'events-template', 'Events', 'Events', 'From milestones to memories in the making, this event is more than just a date on the calendar—it''s a celebration of life, laughter, and the people who make it unforgettable.', 11, array['/templates/events/1.jpg', '/templates/events/2.jpg', '/templates/events/3.jpg', '/templates/events/4.jpg']::text[]),
  ('baby-shower', 'baby-shower-template', 'Baby Shower', 'Baby showers', 'A day filled with love, laughter, and lullabies. This baby shower celebrates the joy of new beginnings, tiny kicks, and the big love growing every day. Here''s to the bundle of joy we can''t wait to meet!', 12, array['/templates/baby-shower/1.jpg', '/templates/baby-shower/2.jpg', '/templates/baby-shower/3.jpg', '/templates/baby-shower/4.jpg']::text[]),
  ('corporate', 'corporate-template', 'Corporate', 'Corporate', 'Highlight milestones, achievements, or company culture with a sleek, newspaper-style template — perfect for internal shoutouts or client-facing celebrations.', 13, array['/templates/corporate/1.jpg', '/templates/corporate/2.jpg', '/templates/corporate/3.jpg', '/templates/corporate/4.jpg']::text[]),
  ('fashion-magazine', 'fashion-magazine-template', 'Fashion Magazine', 'Fashion', 'A tribute to the icons who turned sidewalks into catwalks—every strut, every stare, every statement made. This is where style became identity, where confidence was couture, and where fashion wrote its own rules.', 14, array['/templates/fashion-magazine/1.png', '/templates/fashion-magazine/2.png', '/templates/fashion-magazine/3.png', '/templates/fashion-magazine/4.png']::text[]),
  ('promotion', 'promotion-template', 'Promotion', 'Promotions', 'A nod to the icons in the making—every capsule, every cut, every curve celebrated. This is not just a promo, it''s a personal style revolution.', 15, array['/templates/promotion/1.png', '/templates/promotion/2.png', '/templates/promotion/3.png', '/templates/promotion/4.png']::text[])
insert into public.pricing (id, config) values
